{
  "bioavailability_prediction": "high",
  "claims": [
    {
      "card_ids": ["C14"],
      "claim": "Zolmitriptan, which shares the 3-(2-dimethylaminoethyl)indole core, has a mean oral bioavailability of 38% in young men, supporting F ≥ 20% for the query.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C11"],
      "claim": "Rizatriptan, another close analogue with the same dimethylaminoethyl indole scaffold, has an absolute oral bioavailability of approximately 40% in healthy volunteers, supporting high oral bioavailability.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C62"],
      "claim": "Eletriptan, a sulfone-containing triptan with related structural features, has an absolute oral bioavailability of approximately 50%, showing that sulfone/sulfonamide-type triptans can achieve F ≥ 20%.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C64"],
      "claim": "Naratriptan, a sulfonamide-containing triptan, has an oral bioavailability of 74% in women, demonstrating that the sulfonamide motif itself does not dictate low bioavailability.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C46"],
      "claim": "Sumatriptan, the closest Morgan analogue, has low oral bioavailability of approximately 15% due to presystemic hepatic metabolism and incomplete absorption; however, the query replaces its N-methylsulfonamide with a pyrrolidine sulfonamide, a modification associated with higher bioavailability in the triptan series, so this low-F result is only partially transferable.",
      "evidence_role": "contradictory"
    }
  ],
  "confidence": "moderate",
  "decision_summary": "The query is an almotriptan-like triptan with the same 3-(2-dimethylaminoethyl)indole scaffold as several drugs with F ≥ 20%. Although the closest analogue sumatriptan has low bioavailability (~14-15%), its N-methylsulfonamide is replaced by a pyrrolidine sulfonamide in the query, and the broader triptan evidence (zolmitriptan, rizatriptan, eletriptan, naratriptan) plus the favorable physicochemical prior support F ≥ 20%. Prediction: high.",
  "evidence_gaps": [
    "No direct human bioavailability record for the exact query (almotriptan) is present in the evidence set.",
    "The metabolic and transporter profile of the pyrrolidine sulfonamide substituent is not directly measured; sumatriptan's low F may not fully transfer.",
    "Human F data for the query under the exact F ≥ 20% threshold are not available."
  ],
  "new_evidence_assessment": [],
  "revision_action": "initial"
}

